@startuml

enum EnergyClass {
  A
  B
  C
  D
}

enum EntryType {
  Textual
  Numeric
}

class WebPortal {
  + versionNumber : string
  + urlAddress : string
}

class Building {
  + id : string
  + name : string
  + energyClass : EnergyClass
  + address : string
  + yearOfConstruction : int
}

class AdditionalEntry {
  + name : string
  + value : float
  + unit : string
  + isPublic : boolean
}

class Image {
  + fileName : string
}

class User {
  + userName : string
  + email : string
  + password : string
}

class Administrator extends User {
  + idCardNumber : string
}

class Comment {
  + content : string
}

WebPortal "1" -- "*" Building : provides catalog of
WebPortal "1" -- "*" User : has
Building "1" -- "*" AdditionalEntry : has
Building "1" -- "1..*" Image : has
Building "1" -- "0..1" Image : profile photo
User "1" -- "*" Building : owns
User "1" -- "*" Comment : writes
Building "1" -- "*" Comment : has

@enduml

